def _clean_repository_mess(repo_root: Path) -> dict[str, int]:
    """Surgically remove duplicate root & streamlit_desk .py modules, obsolete files, and stale expired quote JSONs."""
    removed_root_files = 0
    removed_desk_files = 0
    removed_dirs = 0
    removed_expired_quotes = 0

    for py_file in list(repo_root.glob("*.py")):
        if py_file.name not in ALLOWED_ROOT_PY:
            try:
                py_file.unlink()
                removed_root_files += 1
            except OSError:
                pass

    for obs_name in OBSOLETE_ROOT_FILES:
        obs_path = repo_root / obs_name
        if obs_path.is_file():
            try:
                obs_path.unlink()
                removed_root_files += 1
            except OSError:
                pass

    st_desk = repo_root / "streamlit_desk"
    if st_desk.is_dir():
        for py_file in list(st_desk.glob("*.py")):
            if py_file.name not in ALLOWED_DESK_PY:
                try:
                    py_file.unlink()
                    removed_desk_files += 1
                except OSError:
                    pass

    # Remove stray duplicate directories created by earlier patch runs
    vl_dir = repo_root / "Volatility Lab"
    for stray_dir in (
        repo_root / "web",
        repo_root / "underlying_history",
        vl_dir / "web",
        vl_dir / "underlying_history",
    ):
        if stray_dir.is_dir():
            shutil.rmtree(stray_dir, ignore_errors=True)
            removed_dirs += 1

    # Remove expired option_quotes JSONs (<= 2026-11-09) from Volatility Lab/data and data/
    for data_dir in (vl_dir / "data", repo_root / "data"):
        if data_dir.is_dir():
            for q_file in list(data_dir.glob("*_option_quotes_*.json")):
                stem = q_file.stem
                exp_part = stem.split("_option_quotes_")[-1]
                if exp_part <= "2026-11-09":
                    try:
                        q_file.unlink()
                        removed_expired_quotes += 1
                    except OSError:
                        pass

    # Clear stale __pycache__ folders so Python never loads cached bytecode from deleted paths
    for pycache in (
        repo_root / "__pycache__",
        st_desk / "__pycache__",
        vl_dir / "__pycache__",
    ):
        if pycache.is_dir():
            shutil.rmtree(pycache, ignore_errors=True)

    return {
        "removed_root_files": removed_root_files,
        "removed_desk_files": removed_desk_files,
        "removed_dirs": removed_dirs,
        "removed_expired_quotes": removed_expired_quotes,
    }


def _sanitize_and_merge_csv(csv_path: Path, base_csv_text: str, backfill_rows: list[tuple]) -> int:
    """Merge existing CSV (if any) with base 1-year CSV and 3-session backfill, enforcing strict OHLC bounds."""
    csv_path.parent.mkdir(parents=True, exist_ok=True)
    base_df = pd.read_csv(io.StringIO(base_csv_text))
    frames = [base_df]
    if csv_path.exists():
        try:
            existing = pd.read_csv(csv_path)
            if {"Date", "Open", "High", "Low", "Close"}.issubset(existing.columns):
                frames.insert(0, existing[["Date", "Open", "High", "Low", "Close"]])
        except Exception:
            pass
    bf_df = pd.DataFrame(backfill_rows, columns=["Date", "Open", "High", "Low", "Close"])
    frames.append(bf_df)
    merged = pd.concat(frames, ignore_index=True)
    merged["Date"] = pd.to_datetime(merged["Date"].astype(str).str.strip().str[:10], errors="coerce")
    merged = merged.dropna(subset=["Date"]).copy()
    for col in ("Open", "High", "Low", "Close"):
        merged[col] = pd.to_numeric(merged[col], errors="coerce")
    merged = merged.dropna(subset=["Open", "High", "Low", "Close"]).copy()
    merged["High"] = merged[["Open", "High", "Low", "Close"]].max(axis=1)
    merged["Low"] = merged[["Open", "High", "Low", "Close"]].min(axis=1)
    merged["Date"] = merged["Date"].dt.strftime("%Y-%m-%d")
    merged = merged.drop_duplicates(subset=["Date"], keep="last").sort_values("Date").reset_index(drop=True)
    merged.to_csv(csv_path, index=False)
    return len(merged)


def _backfill_research_sqlite(db_path: Path) -> None:
    """Backfill 2026-11-06, 2026-11-08, and 2026-11-09 daily candles into research.sqlite."""
    db_path.parent.mkdir(parents=True, exist_ok=True)
    key_map = {
        "NIFTY": "NSE_INDEX|Nifty 50",
        "BANKNIFTY": "NSE_INDEX|Nifty Bank",
        "INDIA_VIX": "NSE_INDEX|India VIX",
    }
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA journal_mode=DELETE;")
        con.execute(
            "CREATE TABLE IF NOT EXISTS candles ("
            "instrument TEXT, interval TEXT, stamp TEXT, "
            "open REAL, high REAL, low REAL, close REAL, volume REAL, oi REAL, "
            "PRIMARY KEY (instrument, interval, stamp))"
        )
        cols = [r[1] for r in con.execute("PRAGMA table_info(candles)").fetchall()]
        for sym, rows in BACKFILL_ROWS.items():
            inst_key = key_map[sym]
            for d_str, o, h, l, c in rows:
                stamp = f"{d_str}T00:00:00+05:30"
                if len(cols) == 9:
                    con.execute(
                        "INSERT OR REPLACE INTO candles VALUES (?,?,?,?,?,?,?,?,?)",
                        (inst_key, "day", stamp, float(o), float(h), float(l), float(c), 0.0, 0.0),
                    )
                elif len(cols) == 8:
                    con.execute(
                        "INSERT OR REPLACE INTO candles VALUES (?,?,?,?,?,?,?,?)",
                        (inst_key, "day", stamp, float(o), float(h), float(l), float(c), 0.0),
                    )


